#!/usr/bin/env node
/**
 * Build the viewer's self-hosted browser dependency bundle from exact, pinned
 * devDependencies. The generated assets are committed so source installs and
 * standalone archives never need a browser-time CDN request.
 */
import * as fs from 'node:fs';
import * as path from 'node:path';

const ROOT = path.resolve(import.meta.dirname, '..');
const STATIC_DIR = path.join(ROOT, 'src', 'features', 'viewer', 'static');
const BUNDLE_PATH = path.join(STATIC_DIR, 'viewer.vendor.app');
const LICENSE_PATH = path.join(STATIC_DIR, 'viewer.vendor.LICENSES.txt');

const sources = [
  ['cytoscape', 'dist/cytoscape.min.js'],
  ['layout-base', 'layout-base.js'],
  ['cose-base', 'cose-base.js'],
  ['cytoscape-fcose', 'cytoscape-fcose.js'],
  ['prismjs', 'prism.js'],
  ['prismjs', 'components/prism-jsx.min.js'],
  ['prismjs', 'components/prism-typescript.min.js'],
  ['prismjs', 'components/prism-tsx.min.js'],
  ['prismjs', 'components/prism-python.min.js'],
  ['prismjs', 'components/prism-go.min.js'],
  ['prismjs', 'components/prism-rust.min.js'],
  ['prismjs', 'components/prism-java.min.js'],
  ['prismjs', 'components/prism-c.min.js'],
  ['prismjs', 'components/prism-cpp.min.js'],
  ['prismjs', 'components/prism-csharp.min.js'],
  ['prismjs', 'components/prism-ruby.min.js'],
  ['prismjs', 'components/prism-bash.min.js'],
  ['prismjs', 'components/prism-sql.min.js'],
  ['prismjs', 'components/prism-graphql.min.js'],
  ['prismjs', 'components/prism-markup-templating.min.js'],
  ['prismjs', 'components/prism-php.min.js'],
  ['prismjs', 'components/prism-swift.min.js'],
  ['prismjs', 'components/prism-kotlin.min.js'],
  ['prismjs', 'components/prism-scala.min.js'],
  ['prismjs', 'components/prism-dart.min.js'],
  ['prismjs', 'components/prism-lua.min.js'],
  ['prismjs', 'components/prism-r.min.js'],
];

const packageNames = [...new Set(sources.map(([packageName]) => packageName))];
const versions = new Map(packageNames.map((packageName) => [packageName, readPackageVersion(packageName)]));
const generatedFrom = packageNames.map((packageName) => `${packageName}@${versions.get(packageName)}`).join(', ');
const sections = sources.map(([packageName, relativePath]) => {
  const sourcePath = path.join(ROOT, 'node_modules', packageName, relativePath);
  const body = fs.readFileSync(sourcePath, 'utf8').replace(/^\/\/# sourceMappingURL=.*$/gm, '');
  return `\n/* ---- ${packageName}@${versions.get(packageName)} / ${relativePath} ---- */\n${body}\n;`;
});

const banner = `/* GENERATED by scripts/build-viewer-vendor.mjs. DO NOT EDIT.\n * ${generatedFrom}\n * MIT licenses: viewer.vendor.LICENSES.txt\n */\n`;
fs.writeFileSync(BUNDLE_PATH, `${banner}${sections.join('\n')}\n`, 'utf8');

const licenses = packageNames.map((packageName) => {
  const license = fs.readFileSync(path.join(ROOT, 'node_modules', packageName, 'LICENSE'), 'utf8').trim();
  return `${packageName}@${versions.get(packageName)}\n${'='.repeat(packageName.length + String(versions.get(packageName)).length + 1)}\n\n${license}`;
});
fs.writeFileSync(
  LICENSE_PATH,
  `Generated dependency notices for viewer.vendor.app.\n\n${licenses.join('\n\n\n')}\n`,
  'utf8',
);

process.stdout.write(
  `viewer vendor bundle: ${path.relative(ROOT, BUNDLE_PATH)} (${fs.statSync(BUNDLE_PATH).size} bytes)\n`,
);

function readPackageVersion(packageName) {
  const packageJsonPath = path.join(ROOT, 'node_modules', packageName, 'package.json');
  const parsed = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
  if (typeof parsed.version !== 'string' || parsed.version.length === 0) {
    throw new Error(`Missing version in ${packageJsonPath}`);
  }
  return parsed.version;
}
